			UPDATE KEPRQDT /*updateNegoKEPRQDT*/               
               SET ATOB_UNIT_PRICE=#{ATOB_UNIT_PRICE},
                   ATOB_SEND_FLAG='Y',        
                   SND_CHK='N',        
                   SND_DATM=SYSDATE        
             WHERE BUYER=#{BUYER}
               AND QUOTATION_NO=#{QUOTATION_NO}
               AND QUOTATION_SEQ=#{QUOTATION_SEQ}
               AND REVISION=#{REVISION}
               AND STATUS IN ('C','R')


			UPDATE KEPRQDT     /*updateNegoKEPRQDT2*/           
               SET RECV_FLAG='PM'
             WHERE BUYER=#{BUYER}
               AND QUOTATION_NO=#{QUOTATION_NO}
               AND QUOTATION_SEQ=#{QUOTATION_SEQ}
               AND REVISION=#{REVISION}
               AND STATUS IN ('C','R')


			UPDATE KEPQTDT  /*updateNegoKETQTDT*/                  
               SET ATOB_UNIT_PRICE = #{ATOB_UNIT_PRICE}
            WHERE BUYER=#{BUYER}
            AND QUOTATION_NO=#{QUOTATION_NO}
            AND QUOTATION_SEQ=#{QUOTATION_SEQ}
            AND REVISION=#{REVISION}
            AND AGENT=#{AGENT}
            AND BID_SUCCESS_FLAG='Y'        
            AND STATUS IN ('C','R')


			UPDATE ICOMCQDT  /*updateNegoICOMCQDT*/                                                                               
              SET AGENT=#{AGENT}
                  , TARGET_PRICE=#{ATOB_UNIT_PRICE}
                  , UNIT_PRICE=#{ATOB_UNIT_PRICE}
                  , LIST_PRICE=#{STOA_LIST_PRICE}
            WHERE BUYER = (SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE=#{BUYER} AND STATUS IN ('C','R'))    
            AND CONTRACT_NO=#{CONTRACT_NO}
            AND BUYER_ITEM_NO = #{BUYER_ITEM_NO}
            AND (BELOW_COMORG_CODE IN (SELECT BL.COMORG_CODE
                                                                 FROM BYCAORGL BL, ICOMCMPY CP
                                                                WHERE BL.P_COMORG_CODE  IN (SELECT P_COMORG_CODE
                                                                                                            FROM BYCAORGL 
                                                                                                            WHERE COMORG_CODE =  #{BUYER})
                                                                   AND BL.COMORG_CODE = CP.COM_CODE
                                                                   AND CP.STATUS IN ('C','R') 
                                                                   AND #{INIT_BELOW_COMORG_CODE} = 'ALL')
                       OR  BELOW_COMORG_CODE=#{INIT_BELOW_COMORG_CODE} )
            AND STATUS <> 'D'


			INSERT INTO BNTNEGOHISTORY (    /*insertNegoHistory*/                                                
                                      BUYER
									, QUOTATION_NO
									, QUOTATION_SEQ
									, REVISION
									, NEGO_SEQ
									, NEGO_PRICE
									, NEGO_DATE
									, BTOA_NEGO_PRICE
									, BTOA_NEGO_REMARK
									, CREATE_USER_ID 
									, ATOB_UNIT_PRICE         
		          ) ( 
		          SELECT 
					    #{BUYER}
					    , #{QUOTATION_NO}
					    , #{QUOTATION_SEQ}
					    , #{REVISION}
					    , (SELECT NVL(MAX(NEGO_SEQ) + 1, 1) 
					          FROM BNTNEGOHISTORY
					        WHERE BUYER = #{BUYER}
					            AND QUOTATION_NO = #{QUOTATION_NO}
					            AND QUOTATION_SEQ = #{QUOTATION_SEQ}
					            AND REVISION = #{REVISION} )
					    , #{ATOB_UNIT_PRICE}
					    , SYSDATE
					    , #{BTOA_NEGO_PRICE}
					    , #{REJECT_REMARK}
					    , #{st_user_id}
					    , #{QTDT_ATOB_UNIT_PRICE}
					FROM DUAL
		           )


		UPDATE KEPMGPDT /*updateApprovalKEPMGPDT*/
		  SET STATUS = #{STATUS}            
               , CONFIRM_DATE = SYSDATE  
               , CONFIRM_USER_ID = #{USER_ID} 
	       WHERE BUYER = #{KEY_2}
	           AND PM_NO = #{KEY_1}


		UPDATE KEPMGPHD /*updateApprovalKEPMGPHD*/
		  SET STATUS = #{STATUS}            
               , CONFIRM_DATE = SYSDATE  
               , CONFIRM_USER_ID = #{USER_ID} 
               , CONFIRM_USER_DEPT = #{USER_DEPT}
	       WHERE BUYER = #{KEY_2}
	           AND PM_NO = #{KEY_1}


		UPDATE KEPMGPDT /*updateRejectKEPMGPDT*/
		  SET STATUS = #{STATUS}            
               , CONFIRM_DATE = SYSDATE  
               , CONFIRM_USER_ID = #{USER_ID} 
               , CHANGE_DATE = SYSDATE
	       WHERE BUYER = #{KEY_2}
	           AND PM_NO = #{KEY_1}


		UPDATE KEPMGPHD /*updateRejectKEPMGPHD*/
		  SET STATUS = #{STATUS}            
               , CONFIRM_DATE = SYSDATE  
               , CONFIRM_USER_ID = #{USER_ID} 
               , CHANGE_DATE = SYSDATE
	       WHERE BUYER = #{KEY_2}
	           AND PM_NO = #{KEY_1}


		UPDATE KEPMGPDT /*updateCancelKEPMGPDT*/
		  SET STATUS = #{STATUS}            
               , CHANGE_DATE = SYSDATE  
	       WHERE BUYER = #{KEY_2}
	           AND PM_NO = #{KEY_1}


		UPDATE KEPMGPHD /*updateCancelKEPMGPHD*/
		  SET STATUS = #{STATUS}            
               , CHANGE_DATE = SYSDATE
	       WHERE BUYER = #{KEY_2}
	           AND PM_NO = #{KEY_1}

