SELECT DISTINCT BELOW_COMORG_CODE /*getComorgcode*/
	FROM KEPRQDT A
	WHERE A.BUYER = #{KEY_2}    
	               AND (A.QUOTATION_NO, A.QUOTATION_SEQ, A.REVISION) IN (    
	                                                       SELECT A.QUOTATION_NO, A.QUOTATION_SEQ, A.REVISION 
	                                                         FROM KEPMGPDT A    
	                                                       WHERE A.BUYER = #{KEY_2}  
	                                                           AND A.PM_NO = #{KEY_1}    
	                                                           AND A.STATUS<>'D'    
	                                                           )

